      const op = expr[i];
      i++;
      skipSpaces();
      const right = parseTerm();
      if (op === '+') result += right;
      else result -= right;
    }
    return result;
  }

  function parseTerm() {
    let result = parseFactor();
    while (true) {
      skipSpaces();
      if (i >= expr.length || expr[i] === '+' || expr[i] === '-' || expr[i] === '*' || expr[i] === '/') break;
      const op = expr[i];
      i++;
      skipSpaces();
      const right = parseFactor();
      if (op === '*') result *= right;
      else result /= right;
    }
    return result;
  }

  function parseFactor() {
    skipSpaces();
    if (i >= expr.length) throw new Error('Unexpected end');
    if (expr[i] === '(') {
      i++;
      skipSpaces();
      const result = parseExpr();
      skipSpaces();
      if (i >= expr.length || expr[i] !== ')') throw new Error('Missing )');
      i++;
      return result;
    }
    if (expr[i] === '-' || expr[i] === '+') {
      const sign = expr[i] === '-' ? -1 : 1;
      i++;
      skipSpaces();
      const value = parseFactor();
      return sign * value;
    }
    // integer
    let start = i;
    while (i < expr.length && /\d/.test(expr[i])) i++;
    if (i === start) throw new Error('Unexpected character');
    return parseInt(expr.slice(start, i));
  }

  return parseExpr();
}
